public double fractionalKnapsack(int[] value, int[] weight, int W) {
    int n = value.length;
    boolean[] used = new boolean[n];
    double total = 0.0;
    int capacity = W;
    for (int round = 0; round < n && capacity > 0; round++) {
        int best = -1;
        double bestRatio = -1.0;
        for (int i = 0; i < n; i++) {
            if (!used[i]) {
                double ratio = (double) value[i] / weight[i];
                if (ratio > bestRatio) {
                    bestRatio = ratio;
                    best = i;
                }
            }
        }
        if (best == -1) {
            break;
        }
        used[best] = true;
        if (weight[best] <= capacity) {
            total += value[best];
            capacity -= weight[best];
        } else {
            total += value[best] * ((double) capacity / weight[best]);
            capacity = 0;
        }
    }
    return total;
}

