def fractional_knapsack(self, value: list[int], weight: list[int], W: int) -> float:
    n = len(value)
    used = [False] * n
    total = 0.0
    capacity = W
    for _ in range(n):
        if capacity == 0:
            break
        best, best_ratio = -1, -1.0
        for i in range(n):
            if not used[i]:
                ratio = value[i] / weight[i]
                if ratio > best_ratio:
                    best_ratio, best = ratio, i
        if best == -1:
            break
        used[best] = True
        if weight[best] <= capacity:
            total += value[best]
            capacity -= weight[best]
        else:
            total += value[best] * (capacity / weight[best])
            capacity = 0
    return total

