public double fractionalKnapsack(int[] value, int[] weight, int W) {
    int n = value.length;
    Integer[] idx = new Integer[n];
    for (int i = 0; i < n; i++) {
        idx[i] = i;
    }
    // Sort indices by value/weight ratio, descending.
    Arrays.sort(idx, (a, b) -> Double.compare(
        (double) value[b] / weight[b],
        (double) value[a] / weight[a]));
    double total = 0.0;
    long capacity = W;
    for (int i : idx) {
        if (capacity <= 0) {
            break;
        }
        if (weight[i] <= capacity) {
            total += value[i];
            capacity -= weight[i];
        } else {
            total += value[i] * ((double) capacity / weight[i]);
            capacity = 0;
        }
    }
    return total;
}

