def fractional_knapsack(self, value: list[int], weight: list[int], W: int) -> float:
    items = sorted(zip(value, weight), key=lambda vw: vw[0] / vw[1], reverse=True)
    total = 0.0
    capacity = W
    for v, w in items:
        if capacity <= 0:
            break
        if w <= capacity:
            total += v
            capacity -= w
        else:
            total += v * (capacity / w)
            capacity = 0
    return total

